-- Council Training: Council Ready Module 5 rebuilt (2026-11-21).
--
-- "Working with your strata manager and contractors" becomes a fuller
-- module (20 minutes, 30 steps) on working with a licensed strata
-- management company: who is responsible for what, choosing a company,
-- the management agreement, the brokerage's duties and disclosures,
-- communicating, oversight, resolving problems and changing companies,
-- with working with contractors at the end. A knowledge check follows
-- each section and a scenario check finishes it.
--
-- Every legal point was checked against the current consolidations on
-- BC Laws (Strata Property Act; Real Estate Services Rules, B.C. Reg.
-- 209/2021, current to November 17, 2026): SPA ss. 3, 4, 24, 26, 27, 31,
-- 32, 35 to 37, 39 and 92 to 98, the Standard Bylaws on electronic
-- council meetings, and Rules ss. 28, 30, 31, 33, 34, 43, 52, 56, 58, 77
-- and 88.
--
-- Changes only the module's settings (title, summary, length,
-- objectives, further reading and blueprint), never its slides or a
-- published version. If the module already has slides, run Draft with AI
-- again from the module builder, review, and publish. Re-running puts
-- this content back. Paste the whole file into an empty SQL editor tab.

do $$
declare
  v_track uuid;
  v_count int;
begin
  select id into v_track from public.training_tracks where code = 'council_ready';
  if v_track is null then
    raise notice 'Council Ready track not found; nothing changed.';
    return;
  end if;

  update public.training_modules
  set title = $cr6$Working with your strata manager and contractors$cr6$,
      summary = $cr6$Who is responsible for what when a strata hires a licensed management company, how to choose one and read the management agreement, the manager's professional duties, communicating and keeping oversight, resolving problems, changing companies, and hiring contractors well.$cr6$,
      estimated_minutes = 20,
      objectives = $cr6$[{"text": "Explain the responsibilities of the strata corporation, council, the management brokerage, its managing broker and the assigned strata manager", "bloom": "understand"}, {"text": "Evaluate management proposals, management agreements, disclosures and contractor quotes before council decides", "bloom": "evaluate"}, {"text": "Apply clear communication, oversight, escalation and transition practices to the strata's management and contractor relationships", "bloom": "apply"}]$cr6$::jsonb,
      further_reading = $cr6$[{"title": "Strata management services (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/roles-and-responsibilities/strata-property-managers/strata-management-services", "note": "What a strata management company can do for council."}, {"title": "Strata manager licensing (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/roles-and-responsibilities/strata-property-managers/licensing", "note": "Why strata managers must be licensed, and the role of the BC Financial Services Authority (BCFSA)."}, {"title": "Real Estate Services Rules", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/209_2021", "note": "Duties to clients (s. 30), service agreements (s. 43), disclosures (ss. 52, 56, 58), strata trust accounts (s. 77) and records (s. 88)."}, {"title": "Strata Property Act", "url": "https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/98043_00", "note": "Council's duties (ss. 26, 31, 32), records (ss. 35 to 37), management contracts (ss. 24, 39) and spending (ss. 92 to 98)."}, {"title": "Financial best practices (Province of BC)", "url": "https://www2.gov.bc.ca/gov/content/housing-tenancy/strata-housing/operating-a-strata/finances-and-insurance/financial-best-practices", "note": "Practical financial safeguards for councils."}]$cr6$::jsonb,
      blueprint = $cr6$[{"topic": "Understanding the relationship", "activity": "none", "teach": "Core principle for the whole module: a strata management company provides professional services to the strata corporation. It does not replace council, take over council's legal responsibilities, or govern the property on its own.\n- The strata corporation is responsible for managing and maintaining the common property and common assets (Strata Property Act section 3).\n- Council exercises the corporation's powers and performs its duties, subject to the Act, the regulations and the bylaws (sections 4 and 26). Some decisions belong to the owners at a general meeting.\n- Council can hire professional management to help, but handing over a task does not hand over council's responsibility to see that it is done.\n\nThe management agreement is between the strata corporation and the brokerage, not the individual manager, so the brokerage may change the assigned manager, subject to the agreement.\nCouncil decides; management advises, administers, coordinates and carries out council's decisions. For example, a manager can get insurance quotes, explain renewal options and work with the insurance broker, but council must still make sure the insurance the Act requires is in place and make the decisions that are council's to make.\nKey takeaway: council governs. Management advises, administers, coordinates and implements."}, {"topic": "Understanding the relationship", "activity": "accordion", "teach": "The parties and what each is responsible for:\n- Owners: elect council, and approve the budget and other resolutions that need an owner vote.\n- Council: governs for the strata corporation, makes decisions within its authority, and directs and oversees management.\n- Management brokerage: the licensed company the strata contracts with. It delivers the services in the management agreement and must follow the Real Estate Services Act and Rules.\n- Managing broker: must be actively engaged in managing the brokerage, ensure its business is carried out competently and lawfully, supervise its licensees, and keep its records and trust accounts in order (Real Estate Services Rules section 28).\n- Assigned strata manager: the licensee who does the day-to-day work for the brokerage."}, {"topic": "Understanding the relationship", "activity": "knowledge_check", "teach": "Check: who is ultimately responsible for making sure the strata corporation's legal duties are carried out? (The strata council, acting for the strata corporation; not the assigned manager, the managing broker or the president alone.)"}, {"topic": "Choosing a management company", "activity": "none", "teach": "Choosing a management company is a major business decision: a poor fit affects financial reporting, maintenance, owner satisfaction, legal compliance and how well council can work.\n- Define the strata's needs first: size, age, complexity, amenities, location, current challenges and the service level council expects. A small townhouse complex needs different services from a large building with elevators, shared mechanical systems or commercial units.\n- Invite several licensed brokerages to answer the same request for proposal, so the answers can be compared. Ask for: experience and licensing; the proposed manager's experience and how many stratas they look after; administrative, accounting and after-hours emergency support; what is included and what costs extra; financial reporting and record keeping; meeting attendance and communication; fees, extra charges and contract terms; and references from similar stratas.\n- Check each company's and manager's licence with BCFSA, which licenses and regulates strata managers, and ask how they handle hard situations, for example: what happens when council approves an urgent repair and the assigned manager is away?"}, {"topic": "Choosing a management company", "activity": "flip_cards", "teach": "A suggested way to compare proposals consistently; it is not a legal requirement. Rate each candidate from 1 to 5 on each criterion and weight it:\n- Relevant experience and expertise: 25%\n- Scope of services and capacity: 25%\n- Communication and responsiveness: 20%\n- Financial systems and controls: 15%\n- Pricing and contract terms: 15%\nShow what each criterion looks for. Key point: choose the company best equipped to serve the strata, not automatically the lowest price.\nApproving the choice:\n- Hiring a management company is normally a council decision. The owners can direct or restrict council by a majority vote at a general meeting (section 27), so check that no such resolution applies.\n- The fees must be properly authorized, normally in the operating fund budget the owners approve (section 97).\n- Record the decision, the approved terms and who is authorized to sign in the council minutes."}, {"topic": "Choosing a management company", "activity": "knowledge_check", "teach": "Check: two proposals are close, and one is noticeably cheaper but its manager looks after many more stratas and offers no after-hours emergency support. Should council choose it because it is cheaper? (Not automatically: weigh experience, capacity, support and contract terms, and record why the chosen company is the better fit.)"}, {"topic": "The management agreement", "activity": "accordion", "teach": "Read the whole agreement before signing, including schedules, fee tables, exclusions and termination terms. The Real Estate Services Rules (section 43) require a written agreement before strata management services begin, unless the strata waives it, signed by the strata and the brokerage. Besides the parties, the address, the start date, the duration, a general description of the services and the fees, the agreement must cover:\n- Which money the brokerage will hold: operating fund, contingency reserve fund, special levy or other amounts.\n- Termination: when either side may end it, in addition to sections 24 and 39 of the Strata Property Act.\n- Authority: whether the brokerage may sign cheques or make payments, enter into contracts, invest the strata's money, and move money between the strata's trust accounts.\n- Reporting: the timing, frequency and kind of financial statements and other records the strata will receive.\n- Records: which records the brokerage keeps for the strata, including which section 35 records.\n- Privacy: how information about the strata and owners' personal information is used and disclosed.\nCouncil should also agree on meetings, response times, emergency coverage and maintenance coordination."}, {"topic": "The management agreement", "activity": "none", "teach": "Three kinds of authority must line up before money is spent:\n- Contractual authority: what the agreement permits the manager to do, for example pay approved invoices or arrange routine maintenance up to a set amount.\n- Legal authority: what the strata corporation may spend under the Act. A spending limit in the agreement does not override sections 96 to 98: operating fund spending must be in the budget or approved by the owners by a 3/4 vote, contingency reserve fund spending must be approved by the owners, and anything else must fit section 98, such as a small unbudgeted expense within its limit or an emergency.\n- Council's authorization: the specific decision or instruction council has given.\nNot everything is covered by the base fee. Major projects, legal proceedings, insurance claims, warranty work, extra meetings and producing documents may cost extra. Agree on the scope, price and approval before the work starts. Any change to the agreement must be in writing and signed by the strata and the brokerage (Rules section 43(7))."}, {"topic": "The management agreement", "activity": "none", "teach": "Ending an agreement (Strata Property Act section 39):\n- The strata can cancel on 2 months' notice, without liability or penalty and despite anything in the contract, if the owners first approve the cancellation by a 3/4 vote at a general meeting.\n- The management company can cancel on 2 months' notice.\n- No prior approval is needed to cancel the agreement in accordance with its own terms, or to decline to renew it when it expires.\nAgreements made before the first annual general meeting (section 24) end on the earliest of: 4 weeks after the second annual general meeting, the termination date in the contract or agreed by the parties, or a cancellation under section 39. The owners can continue the agreement by a majority vote at the second annual general meeting.\nKey takeaway: the agreement is both a description of the services and the framework for holding the company accountable."}, {"topic": "The management agreement", "activity": "knowledge_check", "teach": "Check: the management agreement lets the manager approve repairs up to $5,000. Does that let the manager spend $5,000 on something that isn't in the budget? (Not on its own: the spending must also be allowed under the Strata Property Act, such as in the budget, approved by the owners, or permitted by section 98.)"}, {"topic": "The manager's duties", "activity": "accordion", "teach": "A licensed brokerage acts for the strata corporation as its client. Its duty is to the corporation, not to the president personally, an individual owner, the developer or a group on council. Under the Real Estate Services Rules, the brokerage and its licensees must, among other duties:\n- Act in the client's best interests (s. 30).\n- Follow the client's lawful instructions and act only within the authority the client gave (s. 30).\n- Advise the client to get independent professional advice on matters outside their expertise, such as legal, engineering or accounting questions (s. 30).\n- Keep the client's information confidential (s. 30).\n- Disclose all known material information about the services (s. 30).\n- Take reasonable steps to avoid conflicts of interest, and disclose any that exist (s. 30).\n- Act honestly (s. 33) and with reasonable care and skill (s. 34).\nThe section 30 duties can be modified or excluded only by agreement, set out clearly in writing (s. 31), so read any such clause carefully. Even then, the brokerage must still supervise its licensees and keep the client's information confidential."}, {"topic": "The manager's duties", "activity": "none", "teach": "Conflicts of interest and benefits to watch for: referral fees from contractors, insurance brokers or other suppliers; benefits from banking, investments or purchases; contractors related to the brokerage; fees charged for strata documents and who keeps them; the brokerage also managing an owner's rental unit; and the brokerage serving several stratas or sections whose interests compete.\nWhat the Rules require:\n- A conflict of interest must be disclosed promptly and fully, in writing, separately from the management agreement (s. 30).\n- Remuneration from anyone other than the strata, such as a referral fee for recommending a contractor, must be disclosed promptly, in writing and separately from the agreement, with its source and its amount or how it is calculated (ss. 52 and 56).\n- If the licensee or an associate expects a benefit from the strata's spending, its nature and extent must be disclosed before the benefit is accepted (s. 58).\nCouncil should ask for these disclosures, review them and record its decisions. A disclosed conflict is not resolved just because it has been disclosed."}, {"topic": "The manager's duties", "activity": "none", "teach": "Council has duties of its own. Each council member must act honestly and in good faith in the best interests of the strata corporation, with the care, diligence and skill of a reasonably prudent person (Strata Property Act section 31). A council member with a conflicting interest must disclose it fully and promptly, not vote, and leave the meeting while the matter is discussed (unless council asks them to stay to provide information) and while council votes (section 32).\nExample: the manager recommends a contractor for a $40,000 repair, and council learns the contractor has a business relationship with the brokerage. Council should ask for written disclosure of the relationship and any benefit, assess the work on its merits, and get other quotes before deciding.\nKey takeaway: management must show loyalty, care, transparency and good judgment; council must still exercise independent oversight."}, {"topic": "The manager's duties", "activity": "knowledge_check", "teach": "Check: the brokerage expects a referral fee from a contractor it is recommending. What must happen? (The brokerage must disclose the fee to the strata promptly and in writing, with its source and amount; disclosure isn't optional, and isn't only needed if owners complain.)"}, {"topic": "Communicating with management", "activity": "none", "teach": "Unclear communication causes much of the frustration in strata management: several council members giving conflicting instructions, requests with no deadline, decisions made informally, and expectations that were never agreed. Communication is a shared responsibility. These are recommended practices, not legal requirements. Agree on:\n- One liaison, usually the president or another authorized council member, with an alternate.\n- One official channel, such as a shared council email address or the management portal.\n- Response times for routine requests, urgent matters and emergencies.\n- Which requests need a council decision and which fall within authority already delegated.\n- Regular reporting, such as an action list.\n- When to escalate to the managing broker."}, {"topic": "Communicating with management", "activity": "flip_cards", "teach": "Three kinds of message, each with an example:\n- Information request: \"Please send the current elevator maintenance agreement for council to review.\" Asking for a document, not approving or changing anything.\n- Request for a recommendation: \"Please get two quotes and give us your recommendation, with the costs and risks.\" Management gathers information; council keeps the decision.\n- Authorized direction: \"Council approved the contractor's quote at its November 18 meeting. Please issue the work order and confirm the date.\" A written instruction carrying out a decision council has made."}, {"topic": "Communicating with management", "activity": "none", "teach": "Put important instructions in writing and record council's decisions in the minutes. Council makes decisions at council meetings; the Standard Bylaws let council meet by electronic means if everyone can communicate with each other. An email thread is not a council decision unless the strata's bylaws provide for deciding that way.\nA shared action list (task, who is responsible, due date, status) shows what is management's job under the agreement, what is council's, and what needs an outside professional.\nOwners may contact management directly, but an individual owner cannot instruct the manager to act for the strata corporation. Management should answer routine questions and refer anything needing a council decision to council. Share personal information only with people who need it (Personal Information Protection Act).\nKey takeaway: clear instructions, one agreed way of communicating, and written follow-through prevent confusion and conflict."}, {"topic": "Communicating with management", "activity": "knowledge_check", "teach": "Check: the manager gets conflicting instructions from two council members. What is the best response? (Ask for clarification through council's agreed communication process; not follow the president automatically or whichever instruction came first.)"}, {"topic": "Keeping oversight", "activity": "none", "teach": "Management may run much of the day-to-day business, but council must check that the agreed services are delivered. Review regularly: budget against actual and large variances; operating fund and contingency reserve fund balances; bank reconciliations and amounts owing; unpaid strata fees; special levy balances and spending; and large or unusual payments and proposed transfers between funds.\nKnow who holds the money, who approves payments and what stops unauthorized payments. Where a brokerage holds the strata's money, the Real Estate Services Rules (section 77) require:\n- Separate trust accounts in the strata's name, including separate accounts for contingency reserve fund money and special levy money if the brokerage holds them.\n- At least two signatures to withdraw from the reserve fund and special levy accounts.\n- A copy of each account's monthly bank statement and reconciliation to the strata within 6 weeks after the end of the month.\nThe Strata Property Act (sections 92 to 98) governs the funds and when money may be spent."}, {"topic": "Keeping oversight", "activity": "none", "teach": "Building operations: management may coordinate inspections, quotes, deficiency lists, contractors and repair reports, depending on the agreement. Council should keep oversight of significant matters such as required inspections, warranties, insurance renewals, major repairs, depreciation reports and emergency planning. For a major project, decide whether routine management is enough or whether to hire an engineer, consultant or project manager.\nRecords and privacy: the records belong to the strata corporation (sections 35 to 37). Make sure the strata can get its records, and that the manager's system is not the only practical way to reach them. Owners are entitled to see them, generally within 2 weeks of a request (section 36). Privacy practices should cover personal information, who can see what, secure storage, retention and disclosure."}, {"topic": "Keeping oversight", "activity": "accordion", "teach": "A suggested quarterly management review, especially useful for larger or more complex stratas. Check whether:\n- Financial statements arrived on schedule.\n- Council's instructions were completed or have an update.\n- The maintenance list is current.\n- Legal and statutory deadlines are known and tracked.\n- Owner correspondence was handled as agreed.\n- Invoices and extra fees were clearly explained.\n- Open issues were escalated appropriately.\nAn item that isn't confirmed is a reason to ask and verify, not proof that the manager breached the agreement.\nKey takeaway: oversight means reviewing results, following up on exceptions and making sure obligations are met, not micromanaging every administrative task."}, {"topic": "Keeping oversight", "activity": "knowledge_check", "teach": "Check: the brokerage holds the strata's contingency reserve fund. How many signatures does the Real Estate Services Rules require to withdraw money from that account? (At least two, from the people the Rules list, such as the managing broker and a council member.)"}, {"topic": "Resolving problems", "activity": "accordion", "teach": "A missed deadline, a disputed invoice or a communication breakdown is not automatically professional misconduct. Tell apart a service issue, a contract disagreement, a legal compliance concern and possible misconduct. A practical way to escalate:\n- Clarify the issue: what happened, what was expected, the agreement term or instruction involved, and the effect on the strata.\n- Raise it with the assigned manager: ask for an explanation and a fix, and confirm the conversation in writing.\n- Escalate to the managing broker: give a short summary, the documents and the outcome council wants. The managing broker must take reasonable steps to deal with possible misconduct or improper or negligent conduct by the brokerage's people (Rules section 28).\n- Get independent advice where there is significant financial, legal, insurance or contract risk.\n- Consider a complaint to BCFSA if there is evidence of possible misconduct. A contract dispute may need a different legal remedy."}, {"topic": "Resolving problems", "activity": "none", "teach": "BCFSA regulates licensed brokerages and licensees under the Real Estate Services Act and Rules, for example professional misconduct, conflicts of interest, mishandling of client money and licensing requirements. It does not decide contract disputes between a strata and its management company, and it does not enforce the Strata Property Act against strata corporations. An individual owner can also report suspected misconduct, such as misuse of funds.\nWhen management disagrees with council: a manager must act only on lawful instructions and within the authority given (Rules section 30), so may decline an instruction they believe is unlawful or outside the agreement. They should explain the concern and suggest a way forward, such as getting specialist advice. Council should tell legitimate professional caution apart from a disagreement about the services.\nKey takeaway: escalate based on documented facts, how serious the issue is and who has authority, not frustration alone."}, {"topic": "Resolving problems", "activity": "knowledge_check", "teach": "Check: council has a serious concern about the assigned manager that it couldn't resolve with them directly. Who should council generally escalate to before considering a complaint to the regulator? (The managing broker.)"}, {"topic": "Changing management companies", "activity": "accordion", "teach": "Changing companies can make sense when expectations are consistently unmet, the strata's needs have changed, or another brokerage is a better fit. Plan carefully so banking, records, maintenance, insurance, owner communications and legal deadlines aren't disrupted. The options:\n- Cancel under section 39(1)(a): a 3/4 vote at a general meeting, then 2 months' notice.\n- The company cancels under section 39(1)(b): 2 months' notice.\n- Cancel in accordance with the agreement's own terms: no prior owner approval needed (section 39(2)).\n- Decline to renew when the agreement expires: no prior owner approval needed (section 39(2)).\n- An agreement made before the first annual general meeting: ends no later than 4 weeks after the second annual general meeting unless the owners continue it by a majority vote at that meeting, or earlier under its terms or section 39 (section 24)."}, {"topic": "Changing management companies", "activity": "none", "teach": "Plan the handover in writing: banking and trust accounts, signing authority and outstanding payments; operating fund, reserve fund and special levy accounting; financial statements, reconciliations and invoices; minutes, bylaws, correspondence and other records; active contracts, maintenance schedules, warranties, insurance and claims; open owner matters, bylaw matters and legal proceedings; access credentials, systems and supplier contacts; and telling owners the new company's start date.\nThe deadlines are different, so treat them separately:\n- Records: the outgoing company must give the strata its section 35 records within 4 weeks after the agreement ends (Strata Property Act section 37).\n- Financial records: on request, the brokerage must provide its trust account records and invoices to the strata or the new brokerage by the later of 2 weeks after the request and 4 weeks after the services end (Rules section 88).\n- Money: the brokerage must promptly transfer control of the strata's money to the strata or the new brokerage, but may keep enough to pay invoices for expenses incurred before the agreement ended (Rules section 77).\nKey takeaway: a good transition protects the strata's operations, finances and records."}, {"topic": "Changing management companies", "activity": "knowledge_check", "teach": "Check: council wants to cancel the management agreement under section 39(1)(a) of the Strata Property Act. What is required? (A resolution passed by a 3/4 vote at an annual or special general meeting, then 2 months' notice; a council vote alone is not enough.)"}, {"topic": "Working with contractors", "activity": "flip_cards", "teach": "Hiring contractors and other professionals well, whether council does it or the manager does it for council:\n- Scope of work: write down exactly what is to be done, so quotes can be compared.\n- Comparable quotes: get more than one for significant work, on the same scope.\n- Conflicts and related parties: ask the contractor, the manager and council members about any relationship, and record the answers.\n- Insurance and licences: check liability insurance, WorkSafeBC coverage and any trade licence or certification the work requires.\n- The contract: price, schedule, warranties, how changes are approved in writing, and any holdback the Builders Lien Act requires.\n- Invoices: approve payment against the contract and approved change orders.\n- Specialists: bring in an engineer, lawyer or accountant when the question is beyond council and management.\nRecord why council chose a proposal. The spending rules in sections 96 to 98 still apply."}, {"topic": "Scenario", "activity": "knowledge_check", "teach": "Scenario check: the manager recommends a contractor for a large repair, but council hasn't seen a written scope or a quote, and doesn't know whether the contractor is connected to the brokerage. What should council get before deciding? (A written scope and quote, comparable quotes, proof of insurance and WorkSafeBC coverage, written disclosure of any relationship or benefit, and confirmation the spending is authorized.) Then close the module: council governs and stays accountable; management advises, administers and carries out lawful instructions; the goal is a working partnership, neither handing over governance nor micromanaging the professional. This training is educational and does not replace the legislation, the strata's bylaws and agreement, or professional advice."}]$cr6$::jsonb
  where track_id = v_track and curriculum_key = 'cr6';
  get diagnostics v_count = row_count;

  if v_count = 0 then
    raise notice 'Council Ready module cr6 (Working with your strata manager and contractors) not found; nothing changed.';
  elsif exists (select 1 from public.training_slides sl join public.training_modules m on m.id = sl.module_id
                where m.track_id = v_track and m.curriculum_key = 'cr6') then
    raise notice 'Module 5 updated. It already has slides: run Draft with AI again from the module builder, review, and publish.';
  else
    raise notice 'Module 5 updated. Open it in the module builder and run Draft with AI.';
  end if;
end $$;
